#!/bin/bash
# nginxWebUI WAF rule tuning watcher (E-395). Started in the background by nwu-start.sh; polls the shared volume
# /nwu-waf every NWU_WAF_POLL seconds (default 3).
#   request          apply id written by nginxWebUI after custom.yaml; applied when it differs from processed
#   custom.yaml      the appsec-config generated by nginxWebUI
#   result.json      {id, status: ok|failed, message, at} written back here
#   last-good.yaml   the last config that was applied successfully; the container always starts with the default
#                    config and this watcher applies last-good.yaml once LAPI is up
#   processed        last handled apply id
#   applying         apply id being reloaded; a failed reload makes crowdsec exit, the next start reports it
#   startup-applying set while last-good.yaml is reloaded at start; if crowdsec dies then, last-good.yaml is dropped
# A config is only reloaded after `crowdsec -t` accepts it; otherwise the previous one is restored.
# Files in /nwu-waf are written through a temp file in the same directory plus mv -f, so a symlink planted there is replaced
# instead of followed; symlinks and other non-regular files are never read (such a request/custom.yaml fails that apply,
# other ones are deleted).
set -u
dir=/nwu-waf
active=/etc/crowdsec/appsec-configs/nwu-custom.yaml
cfg=/etc/crowdsec/config.yaml
poll="${NWU_WAF_POLL:-3}"

log() { echo "nwu-waf: $*" >&2; }

# Files the other container can write are never read in place: snap copies them into a private mktemp directory and the
# checks and reads use the copy, so swapping the file for a symlink or a FIFO between a check and a read has no effect.
# The copy is made by GNU cp (/bin/cp, coreutils is installed in the image): with -P it opens the source with O_NOFOLLOW
# (busybox cp does not), and `timeout` keeps a FIFO swapped in at the last moment from blocking the watcher.
CP=/bin/cp
TIMEOUT=/usr/bin/timeout
DD=/bin/dd
max_size=1048576
snapdir=""
SNAP=""
SNAP_WHY=""
trap 'rm -rf "$snapdir"' EXIT
trap 'exit 143' TERM
trap 'exit 130' INT

# snap <file> : 0 = $SNAP is a regular copy of <file> (remove it after use); 1 = nothing to read (missing, mktemp failed);
# 2 = <file> is a symlink; 3 = <file> is not a regular file, is larger than 1 MiB or could not be copied. For 2 and 3 $SNAP_WHY says why
# and nothing is left in $SNAP.
snap() {
  if [ -z "$snapdir" ]; then
    snapdir="$(mktemp -d /tmp/nwu-snap.XXXXXX)" || { snapdir=""; log "mktemp failed, not reading $1"; return 1; }
    SNAP="$snapdir/copy"
  fi
  rm -f "$SNAP"
  SNAP_WHY=""
  if [ -L "$1" ]; then SNAP_WHY="a symlink"; return 2; fi
  [ -e "$1" ] || return 1
  if [ ! -f "$1" ]; then SNAP_WHY="not a regular file"; return 3; fi
  # ulimit -f (1024-byte blocks) caps the copy a little above 1 MiB, so a device swapped in at the last moment cannot fill /tmp
  if ! ( ulimit -f 1025; exec "$TIMEOUT" 10 "$CP" -P -- "$1" "$SNAP" ) 2>/dev/null; then
    rm -f "$SNAP"
    SNAP_WHY="not a regular file (or larger than 1 MiB)"
    return 3
  fi
  if [ -L "$SNAP" ]; then rm -f "$SNAP"; SNAP_WHY="a symlink"; return 2; fi
  if [ ! -f "$SNAP" ]; then rm -f "$SNAP"; SNAP_WHY="not a regular file"; return 3; fi
  if [ "$(wc -c < "$SNAP")" -gt "$max_size" ]; then rm -f "$SNAP"; SNAP_WHY="not a regular file (larger than 1 MiB)"; return 3; fi
  return 0
}

# put <dest> : stdin -> new temp file next to <dest> -> mv -f onto <dest>. The temp file is created by GNU dd with
# conv=excl (O_CREAT|O_EXCL: never an existing file or symlink) and oflag=nofollow, with umask 022 so it is born 644 and
# needs no chmod (chmod would follow a symlink swapped in after the file was created).
put() {
  local t
  t="$(mktemp -u "$(dirname "$1")/.nwu.XXXXXX")" || return 1
  if ( umask 022; "$TIMEOUT" 10 "$DD" of="$t" conv=excl oflag=nofollow status=none ) && [ -f "$t" ] && [ ! -L "$t" ] && mv -f "$t" "$1"; then
    return 0
  fi
  rm -f "$t"
  return 1
}

# drop_link <file> : when <file> is a symlink, deletes the link and logs it
drop_link() {
  [ -L "$1" ] || return 1
  rm -f "$1"
  log "removed symlink $1"
}

# write_result <id> <ok|failed> <message>
write_result() {
  ID="$1" ST="$2" MSG="$3" AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    yq -n -o=json -I=0 '.id = strenv(ID) | .status = strenv(ST) | .message = strenv(MSG) | .at = strenv(AT)' \
    | put "$dir/result.json"
  printf '%s\n' "$1" | put "$dir/processed"
}

# fail_reason <crowdsec -t output> : the last 2 level=fatal/level=error lines, reduced to their msg="..." text (the whole
# line when it has none); without such lines the last 3 non-empty lines. At most 500 characters.
fail_reason() {
  r="$(printf '%s\n' "$1" | grep -E 'level=(fatal|error)' | tail -n 2 \
    | sed -E 's/^.*msg="//; s/" [a-z_]+=.*$//; s/"$//; s/\\"/"/g' | tr '\n' ' ')"
  [ -n "$(printf %s "$r" | tr -d " ")" ] || r="$(printf '%s\n' "$1" | grep -v '^[[:space:]]*$' | tail -n 3 | tr '\n' ' ')"
  printf '%s' "$r" | cut -c1-500
}

# apply <file> <id> : makes <file> the active config. Empty id = start-up reapply of last-good.yaml (no result.json).
apply() {
  src="$1"
  id="$2"
  cp -f "$active" /tmp/nwu-prev.yaml
  cp -f "$src" "$active"
  if ! out="$(crowdsec -c "$cfg" -t 2>&1)"; then
    cp -f /tmp/nwu-prev.yaml "$active"
    msg="$(fail_reason "$out")"
    log "config test failed, previous config restored: $msg"
    [ -n "$id" ] && write_result "$id" failed "$msg"
    return 1
  fi
  pid="$(pgrep -o -x crowdsec)"
  if [ -z "$pid" ]; then
    cp -f /tmp/nwu-prev.yaml "$active"
    [ -n "$id" ] && write_result "$id" failed "crowdsec process not found"
    return 1
  fi
  if [ -n "$id" ]; then printf '%s\n' "$id" | put "$dir/applying"; else : | put "$dir/startup-applying"; fi
  kill -HUP "$pid"
  sleep 5
  rm -f "$dir/applying" "$dir/startup-applying"
  if ! kill -0 "$pid" 2>/dev/null; then
    [ -n "$id" ] && write_result "$id" failed "crowdsec exited during reload"
    return 1
  fi
  put "$dir/last-good.yaml" < "$active"
  [ -n "$id" ] && write_result "$id" ok ""
  log "applied ${id:-last-good.yaml}"
  return 0
}

wait_lapi() {
  i=0
  while [ "$i" -lt 60 ]; do
    cscli lapi status >/dev/null 2>&1 && return 0
    i=$((i + 1))
    sleep 2
  done
  return 1
}

mkdir -p "$dir"
for f in startup-applying applying last-good.yaml processed; do drop_link "$dir/$f"; done
wait_lapi || log "LAPI not ready after 120s, watching anyway"
if [ -f "$dir/startup-applying" ]; then
  log "crowdsec died while reapplying last-good.yaml at start, dropping it"
  mv -f "$dir/last-good.yaml" "$dir/last-good.broken.yaml" 2>/dev/null || true
  rm -f "$dir/startup-applying"
fi
snap "$dir/applying"
rc=$?
if [ "$rc" -eq 0 ]; then
  id="$(tr -d '[:space:]' < "$SNAP")"
  rm -f "$SNAP" "$dir/applying"
  write_result "$id" failed "crowdsec could not reload this config and restarted; the previous settings are back in use"
elif [ "$rc" -ge 2 ]; then
  rm -f "$dir/applying"
  log "applying is $SNAP_WHY, removed"
fi
snap "$dir/last-good.yaml"
rc=$?
if [ "$rc" -eq 0 ]; then
  if ! cmp -s "$SNAP" "$active"; then
    apply "$SNAP" "" || log "last-good.yaml rejected, keeping the default config"
  fi
  rm -f "$SNAP"
elif [ "$rc" -ge 2 ]; then
  rm -f "$dir/last-good.yaml"
  log "last-good.yaml is $SNAP_WHY, removed"
fi
while true; do
  snap "$dir/request"
  rc=$?
  if [ "$rc" -ge 2 ]; then
    rm -f "$dir/request"
    log "request is $SNAP_WHY, refused"
    write_result refused failed "request is $SNAP_WHY, refused"
  elif [ "$rc" -eq 0 ]; then
    id="$(tr -d '[:space:]' < "$SNAP")"
    rm -f "$SNAP"
    done_id=""
    snap "$dir/processed"
    rc=$?
    if [ "$rc" -eq 0 ]; then
      done_id="$(tr -d '[:space:]' < "$SNAP")"
      rm -f "$SNAP"
    elif [ "$rc" -ge 2 ]; then
      rm -f "$dir/processed"
      log "processed is $SNAP_WHY, removed"
    fi
    if [ -n "$id" ] && [ "$id" != "$done_id" ]; then
      snap "$dir/custom.yaml"
      rc=$?
      if [ "$rc" -ge 2 ]; then
        rm -f "$dir/custom.yaml"
        log "custom.yaml is $SNAP_WHY, refused"
        write_result "$id" failed "custom.yaml is $SNAP_WHY, refused"
      elif [ "$rc" -eq 0 ]; then
        apply "$SNAP" "$id" || true
        rm -f "$SNAP"
      fi
    fi
  fi
  sleep "$poll"
done
